mapper.select:
SELECT agent_id, access_scope, created_at, updated_at
FROM agent_user_policy
WHERE agent_id = #{agentId}

SELECT agent_id, tool_id, access_scope, created_at, updated_at
FROM agent_tool_user_policy
WHERE agent_id = #{agentId}
  AND tool_id = #{toolId}

SELECT COUNT(1)
FROM agent_user_access_policy
WHERE agent_id = #{agentId}
  AND user_id = #{userId}

SELECT COUNT(1)
FROM agent_tool_user_access_policy
WHERE agent_id = #{agentId}
  AND tool_id = #{toolId}
  AND user_id = #{userId}
